import{_ as o,l as t,o as e,c as l,v as n,p as s,x as r,d,i as p,S as m}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"家族企业与金字塔","description":"","frontmatter":{"title":"家族企业与金字塔","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/family-firms-pyramids.md","filePath":"econ/family-firms-pyramids.md","lastUpdated":1789023840000}'),h={name:"econ/family-firms-pyramids.md"};function c(f,a,_,E,u,A){const i=t("Mermaid");return e(),l("div",null,[a[1]||(a[1]=n('<h1 id="家族企业与金字塔" tabindex="-1">家族企业与金字塔 <a class="header-anchor" href="#家族企业与金字塔" aria-label="Permalink to &quot;家族企业与金字塔&quot;">​</a></h1><div class="epigraph"><p>投票权与现金流权分离之后，控制人可以用少数资本指挥多数资产。这是所有权结构，不是企业文化小品。</p><footer>—— La Porta, Lopez-de-Silanes, Shleifer and Vishny 的所有权与法律；Almeida and Wolfenzon 的金字塔</footer></div><p><a href="/econ/esg-theory">上一课</a>问目标函数里有没有非金钱项。缺口是控制权：谁能决定目标。本课钉家族与金字塔，识别课收束本课程。不重写 <a href="/econ/modigliani-miller">MM</a> 资本结构。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>LLSV：许多国家的典型企业不是 Berle–Means 的分散股东，而是家族或国家通过金字塔、交叉持股维持控制。Almeida–Wolfenzon：金字塔便于用内部资本市场配置，也便于掏空。若公司金融实证默认「股东价值最大化的公众公司」，外部有效性只覆盖一种所有权。缺口是把现金流权（C）与投票权（V）分开，隧道（tunneling）是 \\(V\\gt C\\) 时的代理。</p><p><span class="marginnote">Claessens, Djankov and Lang 的东亚金字塔。Johnson 等人的掏空。Burkart, Panunzi and Shleifer 的家族控制权权衡。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>度量：控制链上的投票乘积 vs 现金流乘积。后果：股利、关联交易、职业经理人聘任、危机时的支持（propping）与掏空。与双层股权：同是 \\(V\\neq C\\)，但金字塔跨多家公司。法律：投资者保护弱则金字塔更有价值（LLSV）。与 ESG：控制人偏好可以是王朝、声誉或政治，不必是评级。</p>',8)),(e(),s(m,null,{default:r(()=>[p(i,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20C%5B%22%E7%8E%B0%E9%87%91%E6%B5%81%E6%9D%83%22%5D%20--%3E%20ALIGN%5B%22%E6%BF%80%E5%8A%B1%22%5D%0A%20%20V%5B%22%E6%8A%95%E7%A5%A8%E6%9D%83%22%5D%20--%3E%20CTRL%5B%22%E6%8E%A7%E5%88%B6%22%5D%0A%20%20GAP%5B%22V%20%3E%20C%22%5D%20--%3E%20TUN%5B%22%E6%8E%8F%E7%A9%BA%E9%A3%8E%E9%99%A9%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=n('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>内部资本市场在外部融资贵时有收益；控制权私人收益在保护弱时有成本。均衡所有权结构随法律与资本市场深度变。危机中，控制人可能用私产支持（propping），因为控制权期权还在——这不是利他，是期权价值。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把家族写成低效的代名词。下一课：这些结构使 IV 更难，识别要声明谁在最大化什么。不写某姓氏企业史。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>把投票权与现金流权分开，金字塔是分离的常见技术。</li><li>掏空与支持是同一控制权的两个状态。</li><li>出处：LLSV；Almeida and Wolfenzon；Johnson 等掏空。</li></ul>',6))])}const T=o(h,[["render",c]]);export{S as __pageData,T as default};
